from decimal import Decimal, ROUND_HALF_UP


def _is_blank(value: object) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _fixed(value: object, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def format_account(row: dict) -> str:
    acct_id = _fixed(row.get("ACCT_ID", ""), 10)
    acct_name = _fixed(row.get("ACCT_NM", ""), 40)
    region = _fixed(row.get("REGION_CD", ""), 3)

    revenue = row.get("ANN_REV", "")
    if _is_blank(revenue):
        cents = 0
    else:
        amount = Decimal(str(revenue))
        cents = int((amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        ))

    revenue_field = f"{cents:015d}"

    credit_hold = row.get("CRED_HOLD", "")
    if _is_blank(credit_hold):
        credit_hold = "N"
    else:
        credit_hold = str(credit_hold)

    create_date = row.get("CREATE_DT", "")
    if _is_blank(create_date):
        create_date = "00000000"
    else:
        create_date = str(create_date)

    return acct_id + acct_name + region + revenue_field + credit_hold + create_date
